def _consume_token(tokens: list[Token], expected_type: TokenType, expected_value: str = None) -> Token:
    if not tokens:
        raise SQLSyntaxError("Unexpected end of input")
    token = tokens.pop(0)
    if token.type != expected_type:
        raise SQLSyntaxError(f"Expected {expected_type.value}, got {token.type.value}")
    if expected_value is not None and token.value != expected_value:
        raise SQLSyntaxError(f"Expected {expected_value}, got {token.value}")
    return token

def _parse_column_def(tokens: list[Token]) -> ColumnDef:
    name = _consume_token(tokens, TokenType.IDENTIFIER).value
    _consume_token(tokens, TokenType.KEYWORD)
    column_type = ColumnType(_consume_token(tokens, TokenType.KEYWORD).value)
    return ColumnDef(name, column_type)

def _parse_column_list(tokens: list[Token]) -> tuple[str, ...]:
    _consume_token(tokens, TokenType.OPERATOR, "(")
    columns = []
    while True:
        columns.append(_consume_token(tokens, TokenType.IDENTIFIER).value)
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ")":
            break
        _consume_token(tokens, TokenType.OPERATOR, ",")
    _consume_token(tokens, TokenType.OPERATOR, ")")
    return tuple(columns)

def _parse_values(tokens: list[Token]) -> tuple[Value, ...]:
    _consume_token(tokens, TokenType.OPERATOR, "(")
    values = []
    while True:
        token = _consume_token(tokens, TokenType.LITERAL)
        if token.type == TokenType.INTEGER:
            values.append(int(token.value))
        elif token.type == TokenType.STRING:
            values.append(token.value)
        elif token.type == TokenType.KEYWORD and token.value == "TRUE":
            values.append(True)
        elif token.type == TokenType.KEYWORD and token.value == "FALSE":
            values.append(False)
        elif token.type == TokenType.KEYWORD and token.value == "NULL":
            values.append(None)
        else:
            raise SQLSyntaxError(f"Unexpected literal type: {token.type.value}")
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ")":
            break
        _consume_token(tokens, TokenType.OPERATOR, ",")
    _consume_token(tokens, TokenType.OPERATOR, ")")
    return tuple(values)

