    where_expr = None
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
        _consume_token(tokens, TokenType.KEYWORD, "WHERE")
        where_expr = parse_expression(tokens)
    if where_expr is None:
        where_expr = Literal(True)
    return DeleteStmt(table_name, where_expr)

def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    if not tokens:
        raise SQLSyntaxError("Unexpected end of input")
    token = tokens[0]
    if token.type == TokenType.KEYWORD:
        if token.value == "CREATE":
            stmt = _parse_create_table_stmt(tokens)
        elif token.value == "DROP":
            stmt = _parse_drop_table_stmt(tokens)
        elif token.value == "INSERT":
            stmt = _parse_insert_stmt(tokens)
        elif token.value == "SELECT":
            stmt = _parse_select_stmt(tokens)
        elif token.value == "DELETE":
            stmt = _parse_delete_stmt(tokens)
        else:
            raise SQLSyntaxError(f"Unknown keyword: {token.value}")
    else:
        raise SQLSyntaxError(f"Expected keyword, got {token.type.value}")
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
        _consume_token(tokens, TokenType.OPERATOR, ";")
    _consume_token(tokens, TokenType.EOF)
    return stmt

def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    stmts = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
            stmts.append(stmt)
        except SQLSyntaxError:
            if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
                _consume_token(tokens, TokenType.OPERATOR, ";")
            else:
                raise
    _consume_token(tokens, TokenType.EOF)
    return stmts

def _parse_primary(tokens: list[Token]) -> Expr:
    token = tokens[0]
    if token.type == TokenType.INTEGER:
        _consume_token(tokens, TokenType.INTEGER)
        return Literal(int(token.value))
    elif token.type == TokenType.STRING:
        _consume_token(tokens, TokenType.STRING)
        return Literal(token.value)
    elif token.type == TokenType.KEYWORD and token.value in ("TRUE", "FALSE"):
        _consume_token(tokens, TokenType.KEYWORD)
        return Literal(token.value == "TRUE")
    elif token.type == TokenType.KEYWORD and token.value == "NULL":
        _consume_token(tokens, TokenType.KEYWORD)
        return Literal(None)
    elif token.type == TokenType.IDENTIFIER:
        _consume_token(tokens, TokenType.IDENTIFIER)
        return ColumnRef(token.value)
    elif token.type == TokenType.OPERATOR and token.value == "(":
        _consume_token(tokens, TokenType.OPERATOR, "(")
        expr = parse_expression(tokens)
        _consume_token(tokens, TokenType.OPERATOR, ")")
        return expr
    else:
        raise SQLSyntaxError(f"Unexpected token: {token.type.value}")

def _parse_predicate(tokens: list[Token]) -> Expr:
    left = _parse_primary(tokens)
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
        _consume_token(tokens, TokenType.KEYWORD, "IS")
        negated = False
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            _consume_token(tokens, TokenType.KEYWORD, "NOT")
            negated = True
        _consume_token(tokens, TokenType.KEYWORD, "NULL")
        return IsNull(left, negated)
    elif tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
        op = _consume_token(tokens, TokenType.OPERATOR).value
        right = _parse_primary(tokens)
        return Comparison(op, left, right)
    else:
        return left

def _parse_not_expr(tokens: list[Token]) -> Expr:
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
        _consume_token(tokens, TokenType.KEYWORD, "NOT")
        operand = _parse_not_expr(tokens)
        return Not(operand)
    else:
        return _parse_predicate(tokens)

def _parse_and_expr(tokens: list[Token]) -> Expr:
    left = _parse_not_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
        _consume_token(tokens, TokenType.KEYWORD, "AND")
        right = _parse_not_expr(tokens)
        left = And(left, right)
    return left

def _parse_or_expr(tokens: list[Token]) -> Expr:
    left = _parse_and_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
        _consume_token(tokens, TokenType.KEYWORD, "OR")
        right = _parse_and_expr(tokens)
        left = Or(left, right)
    return left

def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    expr = _parse_or_expr(tokens)
    _consume_token(tokens, TokenType.EOF)
    return expr
